#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct SearchEntitiesHttpRequest {
    term: String,
    max_entries: u8,
    strictness: Option<f32>,
}

impl SearchEntitiesHttpRequest {
    /// Converts the HTTP request body into a domain request.
    fn try_into_domain(self) -> Result<EntitySearchRequest, EntitySearchError> {
        match self.strictness {
            Some(s) => EntitySearchRequest::new_with_strictness(self.term, self.max_entries, s),
            None => EntitySearchRequest::new_strict(self.term, self.max_entries),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntityResponseData {
    entities: Vec<SearchEntity>,
}

impl From<&[Entity]> for SearchEntityResponseData {
    fn from(value: &[Entity]) -> Self {
        let entities = value.iter().map(SearchEntity::from).collect();
        Self { entities }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntity {
    name: String,
    kind: String,
    funder_kind: Option<String>,
}

impl From<&Entity> for SearchEntity {
    fn from(value: &Entity) -> Self {
        Self {
            name: value.name().to_string(),
            kind: value.kind().to_string(),
            funder_kind: value.funder_kind().map(String::from),
        }
    }
}

impl From<EntitySearchError> for ApiError {
    fn from(value: EntitySearchError) -> Self {
        match value {
            EntitySearchError::InvalidTerm(_)
            | EntitySearchError::InvalidStrictness(_)
            | EntitySearchError::TooFewEntries => Self::UnprocessibleEntity(value.to_string()),
            EntitySearchError::UnexpectedError(_) => Self::InternalServerError,
        }
    }
}

pub async fn search_entities<E: EntitySearchService>(
    State(state): State<AppState<E>>,
    Query(query): Query<SearchEntitiesHttpRequest>,
) -> Result<ApiSuccess<SearchEntityResponseData>, ApiError> {
    let domain_req = query.try_into_domain()?;
    state
        .entity_search_service
        .search_entities(&domain_req)
        .await
        .map_err(ApiError::from)
        .map(|ref entities| ApiSuccess::new(StatusCode::OK, entities.as_slice().into()))
}
use axum::{
    Json,
    http::StatusCode,
    response::{IntoResponse, Response},
};
use serde::Serialize;

/// Generic success message
pub struct ApiSuccess<S: Serialize> {
    code: StatusCode,
    response: S,
}

impl<S: Serialize> ApiSuccess<S> {
    /// Creates new instance
    pub const fn new(code: StatusCode, response: S) -> Self {
        Self { code, response }
    }
}

impl<S: Serialize> IntoResponse for ApiSuccess<S> {
    fn into_response(self) -> Response {
        (self.code, Json(self.response)).into_response()
    }
}
use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
};
use thiserror::Error;

#[derive(Error, Debug)]
/// Errors communicated by the HTTP API
pub enum ApiError {
    #[error("internal server error")]
    /// Private error, message should only be logged
    InternalServerError,
    #[error("unable to process malformed request: {0}")]
    /// Bad request from user
    UnprocessibleEntity(String),
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let code = match self {
            Self::InternalServerError => StatusCode::INTERNAL_SERVER_ERROR,
            Self::UnprocessibleEntity(_) => StatusCode::UNPROCESSABLE_ENTITY,
        };
        (code, self.to_string()).into_response()
    }
}
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::{
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{config::ServerConfig, routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Loads server configuration and serves HTTP on port 6999 or an available port.
///
/// # Errors
/// Returns an error if configuration, runtime creation, or server startup fails.
pub fn run_server() -> anyhow::Result<()> {
    dotenvy::dotenv().ok();
    let config = ServerConfig::from_env()?;

    tokio::runtime::Runtime::new()?.block_on(async {
        let listener = match TcpListener::bind("0.0.0.0:6999").await {
            Err(error) if error.kind() == std::io::ErrorKind::AddrInUse => {
                TcpListener::bind("0.0.0.0:0").await?
            }
            result => result?,
        };
        println!(
            "Listening on http://localhost:{}",
            listener.local_addr()?.port()
        );
        serve_exposed(&config, listener).await
    })
}

/// Starts an `exposed` HTTP server
///
/// # Errors
/// - When the HTTP server fails
pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    axum::serve(listener, router).await?;

    Ok(())
}
