use std::{fs::File, io::Write, path::PathBuf};

use exposed::{
    domain::models::entity_search::EntitySearchRequest,
    inbound::{
        cli::config::{DeclarationFetcherConfig, FetcherConfig, LoaderConfig},
        http::{config::ServerConfig, server::serve_exposed},
    },
};
use reqwest::StatusCode;
use serde_json::Value;
use tempfile::{NamedTempFile, TempDir};

mod declarations;
pub use declarations::{DeclarationFunding, FundingEntry, read_declaration_funding};

pub struct Guard {
    port: u16,
}

pub async fn search_entities(
    app: &Guard,
    params: &EntitySearchRequest,
) -> anyhow::Result<Vec<Value>> {
    let client = reqwest::Client::new();

    let port = app.port;

    let (term, strictness, entries) = (params.term(), params.strictness(), params.max_entries());
    let url = format!(
        "http://127.0.0.1:{port}/search?term={term}&&strictness={strictness}&&max_entries={entries}"
    );
    let response = client.get(url).send().await?;

    match response.status() {
        StatusCode::OK => {
            let bytes = response.bytes().await?;
            let data: Value = serde_json::from_slice(&bytes)?;
            let entities = data
                .get("entities")
                .and_then(|d| d.as_array())
                .ok_or(anyhow::anyhow!("unparsable"))?
                .to_vec();
            Ok(entities)
        }
        StatusCode::INTERNAL_SERVER_ERROR => Err(anyhow::anyhow!("something unexpected happened")),
        StatusCode::UNPROCESSABLE_ENTITY => Err(anyhow::anyhow!("bad url")),
        _ => Err(anyhow::anyhow!(
            "something really unexpected happened, investigate"
        )),
    }
}

pub async fn start_app() -> anyhow::Result<Guard> {
    let config = ServerConfig::from_env()?;
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
    let port = listener.local_addr()?.port();
    let _handle = tokio::task::spawn(async move {
        let _ = serve_exposed(&config, listener).await;
        println!("started");
    });

    Ok(Guard { port })
}

pub fn cli_fetcher_config(tmp: &TempDir) -> (NamedTempFile<File>, PathBuf) {
    let config = FetcherConfig {
        batch_size: 100,
        data_dir: tmp.path().to_path_buf(),
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}

pub fn cli_loader_config(tmp: &TempDir) -> (NamedTempFile<File>, PathBuf) {
    let config = LoaderConfig {
        data_dir: tmp.path().to_path_buf(),
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}

pub fn cli_declaration_fetcher_config(tmp: &TempDir) -> (NamedTempFile<File>, PathBuf) {
    let config = DeclarationFetcherConfig {
        data_dir: tmp.path().to_path_buf(),
        // Small pages exercise pagination against the live source.
        batch_size: 5,
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}
# Run declaration resolution

Use Python 3.10 or later. Install the statistical runtime before invoking the CLI. From the repository root, create a Python environment and install the pinned package dependencies:

```sh
python3 -m venv resolution/.venv
resolution/.venv/bin/python -m pip install ./resolution
```

The package pins Splink 4.0.17 and DuckDB 1.4.4. The repository worker script calls the packaged scorer. No packages are installed at resolution runtime. The bundled frozen model supplies every comparison parameter. Its probabilities are computed but uncalibrated.

Configure an explicit interpreter and the ingestion data directory:

```yaml
data_dir: data
resolution_python: resolution/.venv/bin/python
resolution_worker: resolution/worker.py
candidate_budget: 1000000
```

Paths are relative to the invocation directory. `resolution_worker` defaults to `resolution/worker.py`, so invoke from the repository root or supply an absolute path. The budget applies to profile candidates and expanded source-observation pairs. Increase it explicitly when the command refuses a larger candidate set.

Resolve an existing cleaned run:

```sh
cargo run --package exposed --bin exposed -- data declarations resolve exposed/config/declaration-resolution-dev.yaml --ingestion-key UUID
```

The command prints the output path and counts. The bundle contains observation resolutions, payment attributions, candidate decisions, and a manifest. It refuses an existing bundle. Older cleaned schemas require cleaning retained raw capture into a fresh run. Raw files are not needed after the current cleaner has produced the checked pair.

Run worker integration tests against actual Splink:

```sh
resolution/.venv/bin/python -m unittest discover -s resolution/tests -v
```

Run the real CLI test with a build environment that supplies `DATABASE_URL` or the SQLx query cache for existing database adapters:

```sh
EXPOSED_RESOLUTION_PYTHON="$PWD/resolution/.venv/bin/python" cargo test --package exposed --test declaration_resolution_cli -- --ignored
```

This test builds and invokes the current CLI, cleans retained raw evidence, and resolves two charity observations with statistical support and four Gary Lubner donor observations with missing or disagreeing addresses. It checks the actual names in each identity, the real Splink scores, and refusal to overwrite the result. It removes raw evidence before resolution to verify that the resolver reads only cleaned inputs.

Policy `funder-resolution-v2` accepts donor-to-donor links with the same usable normalized name even when addresses are missing or disagree and the real probability is below 0.999. This deliberately accepts same-name false positives. Other role combinations require exact normalized name, exact usable numbered-street address, and probability at least 0.999. Statistical evidence takes precedence when available. Compatible company and entity-kind evidence is required for every link. Fuzzy names stay review candidates. Each named singleton receives a separate provisional run-local identity. See the [resolution policy](../docs/funder-resolution-design.md) for attribution and repeat behavior.
[build-system]
requires = ["setuptools==80.9.0"]
build-backend = "setuptools.build_meta"

[project]
name = "exposed-funder-resolution"
version = "0.1.0"
requires-python = ">=3.10"
dependencies = ["splink==4.0.17", "duckdb==1.4.4"]

[tool.setuptools.packages.find]
include = ["exposed_resolution"]

[tool.setuptools.package-data]
exposed_resolution = ["model.json"]
#!/usr/bin/env bash
set -euo pipefail

repo="$(cd "$(dirname "$0")/../../../../.." && pwd)"
evidence="${1:?Usage: launch.sh EVIDENCE_DIRECTORY}"
cd "$repo"
test -f .git
test -d "$evidence"
evidence="$(cd "$evidence" && pwd)"
test ! -e "$evidence/build.sha256"
git rev-parse HEAD > "$evidence/revision.txt"
git diff HEAD > "$evidence/source.diff"
git status --short > "$evidence/source-status.txt"
python3 -m venv "$evidence/venv"
"$evidence/venv/bin/pip" install pyarrow ./resolution > "$evidence/dependencies.log" 2>&1
"$evidence/venv/bin/pip" freeze > "$evidence/dependencies.txt"

container=""
trap 'if test -n "$container"; then docker logs "$container" > "$evidence/postgres.log" 2>&1; docker rm -f -v "$container" > "$evidence/build-cleanup.log"; fi' EXIT
docker run -d --label exposed.verification=declarations \
	-e POSTGRES_USER=exposed -e POSTGRES_PASSWORD=REDACTED \
	-e POSTGRES_DB=exposed -p 127.0.0.1::5432 postgres:18-alpine \
	> "$evidence/container.id"
container="$(cat "$evidence/container.id")"
for attempt in {1..240}; do
	if docker exec "$container" pg_isready -U exposed -d exposed > /dev/null 2>&1; then
		break
	fi
	sleep 0.5
done
docker exec "$container" pg_isready -U exposed -d exposed
docker exec -i "$container" psql -X -v ON_ERROR_STOP=1 -U exposed -d exposed \
	< db/migrations/20260915000000_initial.up.sql > "$evidence/schema.log" 2>&1
docker exec "$container" psql -X -v ON_ERROR_STOP=1 -U exposed -d exposed \
	-c 'ALTER ROLE exposed SET search_path TO exposed, public' >> "$evidence/schema.log" 2>&1
address="$(docker port "$container" 5432/tcp)"
DATABASE_URL="REDACTED" \
	SQLX_OFFLINE=false CARGO_TARGET_DIR="$repo/target" \
	cargo build --locked --package exposed --bin exposed > "$evidence/build.log" 2>&1
shasum -a 256 target/debug/exposed > "$evidence/build.sha256"
printf '%s\n' "$repo/target/debug/exposed" > "$evidence/binary.txt"
printf 'Built CLI. Evidence: %s\n' "$evidence"
INSERT INTO exposed.declarations (  
    source_declaration_id ,
    member_id ,
    category_id ,
    category_name ,
    fetched_at ,
    registration_date 
) VALUES 
	(
	    1,
	    (SELECT id FROM members WHERE name='John McDonnell'),
	    12,
	    'Employment and earnings',
	    now(),
	    now()
	),
	(
	    2,
	    (SELECT id FROM members WHERE name='John Humphries'),
	    10,
	    'Family members employed',
	    now(),
	    now()
	);

INSERT INTO exposed.funders (funder_name, funder_kind, company_number)
VALUES
    (E'McDonald\'s', 'Company', '123'),
    ('Aaron Banks', 'Individual', NULL);


INSERT INTO exposed.funding_entries (
    source_declaration_id, funder_id, amount, currency, payment_type
) VALUES
    (1, (SELECT id FROM exposed.funders WHERE funder_name = E'McDonald\'s'),
     10, 'GBP', 'Monetary'),
    (2, (SELECT id FROM exposed.funders WHERE funder_name = 'Aaron Banks'),
     100, 'GBP', 'In Kind');

