import { chromium, expect } from '@playwright/test';
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
const evidence = '../target/verification/entity-details-rebase/live';
await mkdir(evidence, { recursive: true });
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1200, height: 900 } });
await context.tracing.start({ screenshots: true, snapshots: true, sources: true });
try {
  const page = await context.newPage();
  await page.goto('http://127.0.0.1:5198/?q=John&strictness=0.65');
  const [memberResponse] = await Promise.all([
    page.waitForResponse(response => response.url().includes('/api/members/1')),
    page.getByRole('link', { name: 'John McDonnell', exact: true }).click(),
  ]);
  assert.equal(memberResponse.status(), 200);
  const member = await memberResponse.json();
  assert.equal(member.declaration_count, 1);
  assert.equal(member.declarations[0].entries[0].amount, '10');
  await expect(page.getByRole('heading', { name: 'Recent declarations', exact: true })).toBeVisible();
  await expect(page.getByRole('heading', { name: member.declarations[0].category_name, exact: true })).toBeVisible();
  const memberAccent = await page.locator('.profile-type').evaluate(element => getComputedStyle(element).color);
  await page.screenshot({ path: `${evidence}/member.png`, fullPage: true });
  const [funderResponse] = await Promise.all([
    page.waitForResponse(response => response.url().includes('/api/funders/')),
    page.getByRole('link', { name: "McDonald's", exact: true }).click(),
  ]);
  assert.equal(funderResponse.status(), 200);
  const funder = await funderResponse.json();
  assert.equal(funder.currencies[0].parties[0].party_name, 'Labour');
  assert.equal(funder.currencies[0].parties[0].amount, '10');
  assert.equal(funder.currencies[0].top_recipients[0].member.id, member.member.id);
  await expect(page.getByRole('heading', { name: 'Declared support by party', exact: true })).toBeVisible();
  await expect(page.getByRole('heading', { name: 'Top recipients', exact: true })).toBeVisible();
  const funderAccent = await page.locator('.profile-type').evaluate(element => getComputedStyle(element).color);
  assert.notEqual(funderAccent, memberAccent);
  await page.reload();
  await expect(page.getByRole('heading', { name: "McDonald's", exact: true })).toBeVisible();
  await page.setViewportSize({ width: 360, height: 780 });
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true);
  await page.screenshot({ path: `${evidence}/funder-mobile.png`, fullPage: true });
  await page.getByRole('link', { name: 'John McDonnell', exact: true }).click();
  await expect(page.getByRole('heading', { name: 'Recent declarations', exact: true })).toBeVisible();
  await page.getByRole('link', { name: 'Back to search', exact: true }).click();
  assert.equal(new URL(page.url()).searchParams.get('q'), 'John');
  assert.equal(new URL(page.url()).searchParams.get('strictness'), '0.65');
  await expect(page.getByRole('link', { name: 'John McDonnell', exact: true })).toBeVisible();
  await writeFile(`${evidence}/proof.json`, JSON.stringify({ member, funder, memberAccent, funderAccent, searchRestored: true, mobileFits: true }, null, 2));
  console.log('Live API and browser passed: search, MP declarations, funder totals, recipient links, reload, mobile, return to search.');
} finally {
  await context.tracing.stop({ path: `${evidence}/trace.zip` });
  await browser.close();
}
